import { connect } from "cloudflare:sockets";

/* ========== 只有这两个变量需要改 ========== */
const UUID = "ef9d104e-ca0e-4202-ba4b-a0afb969c747"; // 换成你自己的 UUID
const PROXYIP = "proxyip.cmliussss.net";               // 反代：直连目标拿不到数据时改走它
/* ========================================== */

// 客户端入口（优选域名），增删这一串即可
const BEST_IPS = [
  "cloudflare.182682.xyz",
  "cf.090227.xyz",
  "ip.164746.xyz",
  "www.visa.com",
  "www.shopify.com",
  "www.whoer.net",
  "www.udemy.com",
  "ip.sb",
  "www.digitalocean.com",
  "time.is",
  "www.gov.se",
  "icook.hk",
  "cloudflare-ip.mofashi.ltd",
];

const PORT = 443;
const PATH = "/";
const FALLBACK_MS = 100; // 直连这么久没回数据就改走反代

/* ---------------- trojan 密码 = sha224(uuid)（用到才算，模块加载期不做任何事） ---------------- */
function sha224(s) {
  const K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];
  const r = (n, b) => ((n >>> b) | (n << (32 - b))) >>> 0;
  const msg = new TextEncoder().encode(s);
  const total = ((msg.length + 9 + 63) >> 6) << 6; // 补位到 64 字节对齐
  const buf = new Uint8Array(total);
  buf.set(msg);
  buf[msg.length] = 0x80;
  const dv = new DataView(buf.buffer);
  const bits = msg.length * 8;
  dv.setUint32(total - 8, Math.floor(bits / 4294967296));
  dv.setUint32(total - 4, bits >>> 0);
  const h = [0xc1059ed8, 0x367cd507, 0x3070dd17, 0xf70e5939, 0xffc00b31, 0x68581511, 0x64f98fa7, 0xbefa4fa4];
  const w = new Uint32Array(64);
  for (let i = 0; i < total; i += 64) {
    for (let j = 0; j < 16; j++) w[j] = dv.getUint32(i + j * 4);
    for (let j = 16; j < 64; j++) {
      const a = w[j - 15], b = w[j - 2];
      w[j] = (w[j - 16] + (r(a, 7) ^ r(a, 18) ^ (a >>> 3)) + w[j - 7] + (r(b, 17) ^ r(b, 19) ^ (b >>> 10))) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let j = 0; j < 64; j++) {
      const t1 = (hh + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[j] + w[j]) >>> 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, hh].forEach((v, j) => (h[j] = (h[j] + v) >>> 0));
  }
  return h.slice(0, 7).map((v) => v.toString(16).padStart(8, "0")).join("");
}
let pwdCache = "";
const trojanPwd = () => pwdCache || (pwdCache = sha224(UUID));

/* ---------------- 请求解析（纯函数） ---------------- */
// 地址类型统一成 VLESS 的编号：1=IPv4 2=域名 3=IPv6
function readAddr(dv, buf, pos, t) {
  if (t === 1) return [buf[pos] + "." + buf[pos + 1] + "." + buf[pos + 2] + "." + buf[pos + 3], pos + 4];
  if (t === 2) { const l = buf[pos]; pos += 1; return [new TextDecoder().decode(buf.subarray(pos, pos + l)), pos + l]; }
  if (t === 3) { const p = []; for (let i = 0; i < 8; i++, pos += 2) p.push(dv.getUint16(pos).toString(16)); return [p.join(":"), pos]; }
  return [null, pos];
}

// 不是合法请求返回 null，否则 {host, port, payload, header}
function parseVless(buf) {
  if (buf.byteLength < 24) return null;
  const hex = UUID.replace(/-/g, "").toLowerCase();
  for (let i = 0; i < 16; i++) if (buf[i + 1] !== parseInt(hex.substr(i * 2, 2), 16)) return null;
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const optLen = buf[17];
  if (buf[18 + optLen] !== 1) return null; // 只处理 TCP
  const pos = 19 + optLen;
  const port = dv.getUint16(pos);
  const [host, next] = readAddr(dv, buf, pos + 3, buf[pos + 2]);
  if (!host) return null;
  return { host, port, payload: buf.subarray(next), header: new Uint8Array([buf[0], 0]) };
}

function parseTrojan(buf) {
  if (buf.byteLength < 64) return null;
  if (buf[56] !== 0x0d || buf[57] !== 0x0a) return null;
  if (new TextDecoder().decode(buf.subarray(0, 56)) !== trojanPwd()) return null;
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const pos = 58;
  if (buf[pos] !== 1) return null; // 只处理 TCP
  const at = buf[pos + 1];
  const t = at === 1 ? 1 : at === 3 ? 2 : at === 4 ? 3 : 0; // SOCKS 编号 → VLESS 编号
  const [host, next] = readAddr(dv, buf, pos + 2, t);
  if (!host) return null;
  return { host, port: dv.getUint16(next), payload: buf.subarray(next + 2), header: null };
}

/* ---------------- 隧道 ---------------- */
function closeWs(ws) {
  try { ws.readyState === 1 && ws.close(); } catch {}
}

async function startTunnel(first, ws, state) {
  const req = parseTrojan(first) || parseVless(first);
  if (!req) return closeWs(ws);
  const respHeader = req.header;
  const firstData = req.payload;
  let fellBack = false;

  // 把远端 socket 接到 ws 上，返回「是否拿到响应数据」
  const attach = async (sock) => {
    let head = respHeader, got = false, done;
    const waitData = new Promise((r) => (done = r));
    const timer = setTimeout(() => { if (!got) done(false); }, FALLBACK_MS);
    sock.readable
      .pipeTo(
        new WritableStream({
          async write(chunk, ctrl) {
            clearTimeout(timer);
            got = true;
            done(true);
            if (ws.readyState !== 1) return ctrl.error("ws closed");
            if (head) {
              const out = new Uint8Array(head.length + chunk.byteLength);
              out.set(head, 0);
              out.set(chunk, head.length);
              ws.send(out.buffer);
              head = null;
            } else ws.send(chunk);
          },
          abort() {},
        }),
      )
      .catch(() => closeWs(ws));
    if (firstData.byteLength) {
      const w = sock.writable.getWriter();
      await w.write(firstData);
      w.releaseLock();
    }
    return waitData;
  };

  const dial = async (hostname, port) => {
    const sock = connect({ hostname, port });
    state.remote = sock;
    await sock.opened;
    return sock;
  };

  const viaProxy = async () => {
    if (fellBack) return;
    fellBack = true;
    try { state.remote?.close(); } catch {}
    try { await attach(await dial(PROXYIP, PORT)); } catch { closeWs(ws); }
  };

  try {
    if (!(await attach(await dial(req.host, req.port)))) await viaProxy();
  } catch {
    await viaProxy();
  }
}

function onWebSocket(request) {
  const [client, ws] = Object.values(new WebSocketPair());
  ws.accept();
  const state = { remote: null, started: false };

  new ReadableStream({
    start(ctrl) {
      ws.addEventListener("message", (e) => ctrl.enqueue(e.data));
      ws.addEventListener("close", () => {
        try { state.remote?.close(); } catch {}
        try { ctrl.close(); } catch {}
      });
      ws.addEventListener("error", () => { try { ctrl.close(); } catch {} });
      // 0-RTT：客户端把首包塞在 sec-websocket-protocol 里
      const early = request.headers.get("sec-websocket-protocol");
      if (early && early !== "binary") {
        try {
          const s = atob(early.replace(/-/g, "+").replace(/_/g, "/"));
          ctrl.enqueue(Uint8Array.from(s, (c) => c.charCodeAt(0)).buffer);
        } catch {}
      }
    },
  })
    .pipeTo(
      new WritableStream({
        async write(data) {
          const buf = typeof data === "string" ? new TextEncoder().encode(data) : data instanceof ArrayBuffer ? new Uint8Array(data) : new Uint8Array(await new Response(data).arrayBuffer());
          if (!state.started) {
            state.started = true;
            startTunnel(buf, ws, state).catch(() => closeWs(ws));
            return;
          }
          if (!state.remote) return;
          try {
            const w = state.remote.writable.getWriter();
            await w.write(buf);
            w.releaseLock();
          } catch { closeWs(ws); }
        },
      }),
    )
    .catch(() => {});

  return new Response(null, { status: 101, webSocket: client });
}

/* ---------------- 节点与订阅 ---------------- */
function buildNodes(host) {
  return BEST_IPS.flatMap((d) => [
    { name: "V · " + d, kind: "vless", addr: d, pwd: UUID, port: PORT, host, path: PATH },
    { name: "T · " + d, kind: "trojan", addr: d, pwd: UUID, port: PORT, host, path: PATH },
  ]);
}

const nodeURI = (n) =>
  `${n.kind}://${n.pwd}@${n.addr}:${n.port}?${n.kind === "vless" ? "encryption=none&" : ""}security=tls&sni=${n.host}&fp=chrome&type=ws&host=${n.host}&path=${encodeURIComponent(n.path)}#${encodeURIComponent(n.name)}`;

const b64 = (s) => {
  const b = new TextEncoder().encode(s);
  let out = "";
  for (let i = 0; i < b.length; i += 0x8000) out += String.fromCharCode.apply(null, b.subarray(i, i + 0x8000));
  return btoa(out);
};

const G1 = "节点选择";
const G2 = "自动选择";

function toClash(list) {
  const refs = list.map((n) => `      - "${n.name}"`).join("\n");
  return [
    "proxies:",
    ...list.map((n) =>
      [
        `  - name: "${n.name}"`,
        `    type: ${n.kind}`,
        `    server: ${n.addr}`,
        `    port: ${n.port}`,
        `    ${n.kind === "vless" ? "uuid" : "password"}: ${n.pwd}`,
        "    tls: true",
        `    ${n.kind === "vless" ? "servername" : "sni"}: ${n.host}`,
        n.kind === "vless" ? "    client-fingerprint: chrome" : "    skip-cert-verify: false",
        "    network: ws",
        "    ws-opts:",
        `      path: "${n.path}"`,
        "      headers:",
        `        Host: ${n.host}`,
      ].join("\n"),
    ),
    "proxy-groups:",
    `  - name: ${G1}`,
    "    type: select",
    "    proxies:",
    `      - ${G2}`,
    "      - DIRECT",
    refs,
    `  - name: ${G2}`,
    "    type: url-test",
    "    url: http://www.gstatic.com/generate_204",
    "    interval: 300",
    "    tolerance: 50",
    "    proxies:",
    refs,
    "rules:",
    "  - GEOIP,CN,DIRECT",
    `  - MATCH,${G1}`,
  ].join("\n");
}

function toSingbox(list) {
  const names = list.map((n) => n.name);
  return JSON.stringify(
    {
      log: { level: "warn", timestamp: true },
      dns: {
        servers: [
          { tag: "proxy", address: "https://1.1.1.1/dns-query", detour: G1 },
          { tag: "direct", address: "https://223.5.5.5/dns-query", detour: "DIRECT" },
        ],
        rules: [{ outbound: "any", server: "proxy" }],
        final: "proxy",
      },
      inbounds: [{ type: "mixed", tag: "mixed-in", listen: "127.0.0.1", listen_port: 2080 }],
      outbounds: [
        ...list.map((n) => ({
          type: n.kind,
          tag: n.name,
          server: n.addr,
          server_port: n.port,
          ...(n.kind === "vless" ? { uuid: n.pwd } : { password: n.pwd }),
          tls: { enabled: true, server_name: n.host, insecure: false, utls: { enabled: true, fingerprint: "chrome" } },
          transport: { type: "ws", path: n.path, headers: { Host: n.host } },
        })),
        { type: "selector", tag: G1, outbounds: [G2, ...names], default: G2 },
        { type: "urltest", tag: G2, outbounds: names, url: "http://www.gstatic.com/generate_204", interval: "5m", tolerance: 50 },
        { type: "direct", tag: "DIRECT" },
      ],
      route: {
        rules: [{ action: "sniff" }, { protocol: "dns", action: "hijack-dns" }, { ip_is_private: true, outbound: "DIRECT" }],
        final: G1,
      },
    },
    null,
    2,
  );
}

function toSurge(list) {
  const t = list.filter((n) => n.kind === "trojan"); // Surge 不支持 vless
  return [
    "[Proxy]",
    ...t.map((n) => `${n.name} = trojan, ${n.addr}, ${n.port}, password=${n.pwd}, sni=${n.host}, ws=true, ws-path=${n.path}, ws-headers=Host:${n.host}`),
    "[Proxy Group]",
    `${G1} = select, ${t.map((n) => n.name).join(", ")}`,
    "[Rule]",
    "GEOIP,CN,DIRECT",
    `FINAL,${G1}`,
  ].join("\n");
}

function handleSub(request, host) {
  const ua = (request.headers.get("user-agent") || "").toLowerCase();
  const list = buildNodes(host);
  const send = (body, type, refresh) =>
    new Response(body, { headers: { "content-type": type, ...(refresh ? { "profile-update-interval": "12" } : {}) } });
  if (/clash|mihomo|stash/.test(ua)) return send(toClash(list), "text/yaml; charset=utf-8", true);
  if (/sing-?box/.test(ua)) return send(toSingbox(list), "application/json; charset=utf-8");
  if (/surge/.test(ua)) return send(toSurge(list), "text/plain; charset=utf-8", true);
  return send(b64(list.map(nodeURI).join("\n")), "text/plain; charset=utf-8");
}

/* ---------------- 页面 ---------------- */
const pageHTML = (subURL, count) => `<!DOCTYPE html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>节点订阅</title>
<style>
*{box-sizing:border-box}body{margin:0;padding:24px;font:16px/1.6 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#f5f7fb;color:#1e293b}
.wrap{max-width:560px;margin:12vh auto 0}h1{font-size:22px;margin:0 0 8px}p{margin:0 0 20px;color:#64748b;font-size:14px}
.url{padding:14px 16px;border:1px solid #cbd5e1;border-radius:10px;background:#fff;font:13px/1.5 Consolas,Monaco,monospace;word-break:break-all;user-select:all}
button{width:100%;margin-top:14px;padding:13px;border:0;border-radius:10px;background:#2563eb;color:#fff;font-size:15px;font-weight:600;cursor:pointer}
button:active{background:#1d4ed8}.tip{margin:12px 0 0;font-size:12.5px;color:#94a3b8}
</style></head><body><div class="wrap">
<h1>节点订阅</h1>
<p>把下面的订阅链接复制到客户端（v2rayN / Clash / Sing-box / Shadowrocket 都认，会自动识别格式）。</p>
<div class="url" id="u">${subURL}</div>
<button id="b">复制订阅链接</button>
<p class="tip">共 ${count} 个节点</p>
</div>
<script>
document.getElementById('b').onclick = function () {
  var t = document.getElementById('u').textContent, b = this;
  var done = function () { b.textContent = '已复制'; setTimeout(function () { b.textContent = '复制订阅链接'; }, 1500); };
  if (navigator.clipboard) navigator.clipboard.writeText(t).then(done, done); else done();
};
</script></body></html>`;

const blankPage = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Hello</title></head><body style="font:16px/1.6 sans-serif;padding:40px">Hello World</body></html>`;
const HTML = { "content-type": "text/html; charset=utf-8" };

export default {
  fetch(request) {
    try {
      const url = new URL(request.url);
      if (request.headers.get("Upgrade")?.toLowerCase() === "websocket") return onWebSocket(request);
      const host = url.hostname;
      if (url.searchParams.get("uuid") !== UUID) return new Response(blankPage, { headers: HTML });
      if (url.pathname === "/sub") return handleSub(request, host);
      return new Response(pageHTML(`https://${host}/sub?uuid=${UUID}`, buildNodes(host).length), { headers: HTML });
    } catch (e) {
      // 出错时直接把原因显示出来，方便定位（不然只会看到 Cloudflare 的 Error 1101）
      return new Response("Worker error: " + (e && e.stack ? e.stack : e), { status: 500, headers: { "content-type": "text/plain; charset=utf-8" } });
    }
  },
};
